<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Executive Project Monitor</title>
    <link rel="icon" type="image/png" href="https://tazaka.co.id/assets/logo-tazaka-PPqkEZXu.png">
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.9/dist/chart.umd.min.js"></script>
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <style>
        *{box-sizing:border-box}body{margin:0;background:#070b14;color:#f8fafc;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.wrap{max-width:1600px;margin:auto;padding:30px}.header{display:flex;align-items:center;gap:14px;margin-bottom:24px}.header-logo{width:54px;height:54px;object-fit:contain;border-radius:12px;background:#fff;padding:6px;box-shadow:0 8px 24px rgba(0,0,0,.25)}.eyebrow{font-size:11px;letter-spacing:.2em;color:#38bdf8;font-weight:800;text-transform:uppercase}.title{font-size:27px;font-weight:850;margin:5px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.kpi,.card{background:#0d1320;border:1px solid #1e293b;border-radius:18px}.kpi{padding:20px}.kpi-label{font-size:12px;color:#94a3b8}.kpi-value{font-size:32px;font-weight:850;margin-top:8px}.layout-main{display:grid;grid-template-columns:minmax(0,1fr) 460px;gap:18px;align-items:stretch}.card{padding:20px}.card h2{font-size:16px;margin:0 0 18px}.project-card{min-width:0}.project-table-wrap{overflow-x:auto;border:1px solid #1e293b;border-radius:14px;background:#0a101b}.project-table{width:100%;min-width:860px;border-collapse:separate;border-spacing:0;text-align:left}.project-table th{padding:13px 14px;background:#111827;border-bottom:1px solid #263246;color:#64748b;font-size:9px;letter-spacing:.1em;text-transform:uppercase;font-weight:850;white-space:nowrap}.project-table td{padding:15px 14px;border-bottom:1px solid rgba(51,65,85,.45);font-size:12px;vertical-align:middle}.project-table tbody tr:last-child td{border-bottom:0}.project-row{cursor:pointer;transition:background .18s ease}.project-row:hover{background:rgba(30,41,59,.55)}.project-row:focus-visible{outline:2px solid #38bdf8;outline-offset:-2px}.project-name-cell{min-width:190px}.project-name{font-size:13px;font-weight:850;color:#f8fafc;line-height:1.3}.project-client-cell{min-width:170px;max-width:240px}.project-client{font-size:12px;font-weight:850;color:#f8fafc;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.project-type{font-size:10px;color:#cbd5e1;white-space:nowrap}.progress-cell{min-width:130px;width:130px}.progress-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:6px}.progress-percent{font-size:11px;font-weight:850;color:#e2e8f0}.progress{height:7px;background:#172033;border-radius:99px;overflow:hidden}.bar{height:100%;border-radius:99px;transition:width .7s ease,background .35s ease}.target-cell{white-space:nowrap;color:#cbd5e1;font-size:11px}.days-cell{white-space:nowrap}.days-value{font-size:11px;font-weight:850}.map-card{min-width:0}.map-wrap{height:100%;min-height:330px;border-radius:14px;overflow:hidden;border:1px solid #1e293b}.map{width:100%;height:100%;background:#0a101b}.leaflet-container{font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#0b1220}.leaflet-popup-content-wrapper,.leaflet-popup-tip{background:#0d1320;color:#f8fafc}.leaflet-popup-content{font-size:12px;line-height:1.5}.leaflet-control-zoom a{background:#0d1320;color:#f8fafc;border-color:#334155}.charts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.chart-wrap{height:280px}.chart-col:last-child{grid-column:2}.detail-backdrop{position:fixed;inset:0;z-index:1000;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(2,6,23,.78);backdrop-filter:blur(8px)}.detail-backdrop.open{display:flex}.detail-modal{position:relative;width:min(720px,100%);max-height:90vh;overflow:auto;border:1px solid rgba(148,163,184,.22);border-radius:26px;background:linear-gradient(145deg,#121d31,#090f1c);box-shadow:0 30px 80px rgba(0,0,0,.55);padding:28px}.detail-close{position:absolute;top:16px;right:16px;width:36px;height:36px;border:1px solid #334155;border-radius:50%;background:#111827;color:#cbd5e1;font-size:22px;line-height:1;cursor:pointer}.detail-close:hover{background:#1e293b;color:#fff}.detail-eyebrow{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:#38bdf8;font-weight:800}.detail-title{font-size:30px;line-height:1.15;margin:7px 45px 5px 0;font-weight:850}.detail-client{color:#94a3b8;font-size:13px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:24px}.detail-item{padding:14px;border:1px solid #1e293b;border-radius:14px;background:rgba(15,23,42,.55)}.detail-label{font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:#64748b}.detail-value{font-size:13px;color:#e2e8f0;font-weight:700;margin-top:5px}.detail-progress{margin-top:22px}.detail-progress-head{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#94a3b8;margin-bottom:8px}.detail-progress-head strong{color:#f8fafc;font-size:18px}.detail-bar{height:9px;border-radius:99px;background:#1e293b;overflow:hidden}.detail-bar span{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#38bdf8,#67e8f9);transition:width .7s ease}.detail-section{margin-top:22px}.detail-section h3{font-size:12px;margin:0 0 8px;color:#cbd5e1;text-transform:uppercase;letter-spacing:.1em}.detail-text{font-size:13px;line-height:1.7;color:#94a3b8;white-space:pre-wrap}.detail-hint{margin-top:20px;font-size:10px;color:#475569}@media(max-width:1000px){.kpis{grid-template-columns:1fr 1fr}.layout-main{grid-template-columns:1fr}.map-wrap{height:360px}.charts{grid-template-columns:1fr}}@media(max-width:600px){.wrap{padding:16px}.header-logo{width:46px;height:46px}.title{font-size:22px}.project-table{min-width:820px}.project-table th,.project-table td{padding:12px 10px}.detail-modal{padding:22px}.detail-title{font-size:24px}.detail-grid{grid-template-columns:1fr}}
    </style>
</head>
<body>
<div class="wrap">
    <header class="header"><img class="header-logo" src="https://tazaka.co.id/assets/logo-tazaka-PPqkEZXu.png" alt="Logo Tazaka"><div><div class="eyebrow">Tazaka Elektrik Mandiri</div><div class="title">Executive Project Monitor</div></div></header>
    <section class="kpis"><div class="kpi"><div class="kpi-label">TOTAL PROJECT</div><div class="kpi-value" id="total">0</div></div><div class="kpi"><div class="kpi-label">RUNNING</div><div class="kpi-value" id="running">0</div></div><div class="kpi"><div class="kpi-label">COMPLETED</div><div class="kpi-value" id="completed">0</div></div><div class="kpi"><div class="kpi-label">AVG PROGRESS</div><div class="kpi-value"><span id="average">0</span>%</div></div></section>
    <section class="layout-main"><div class="card project-card"><h2>Active Projects</h2><div id="projects" class="project-table-wrap"></div></div><div class="card map-card"><h2>Project Locations</h2><div class="map-wrap"><div id="projectMap" class="map"></div></div></div></section>
    <section class="charts"><div class="card chart-col"><h2>Project Type</h2><div class="chart-wrap"><canvas id="projectTypeChart"></canvas></div></div><div class="card chart-col"><h2>Overall Progress</h2><div class="chart-wrap"><canvas id="progressChart"></canvas></div></div></section>
</div>
<div id="projectDetail" class="detail-backdrop" aria-hidden="true"><div class="detail-modal" role="dialog" aria-modal="true" aria-labelledby="detailTitle"><button type="button" class="detail-close" id="detailClose" aria-label="Close">×</button><div class="detail-eyebrow">Project Detail</div><div class="detail-title" id="detailTitle">-</div><div class="detail-client" id="detailClient">-</div><div class="detail-grid"><div class="detail-item"><div class="detail-label">Project Type</div><div class="detail-value" id="detailType">-</div></div><div class="detail-item"><div class="detail-label">Project Month</div><div class="detail-value" id="detailMonth">-</div></div><div class="detail-item"><div class="detail-label">Target Completion</div><div class="detail-value" id="detailTarget">-</div></div><div class="detail-item"><div class="detail-label">Location</div><div class="detail-value" id="detailLocation">-</div></div></div><div class="detail-progress"><div class="detail-progress-head"><span>Overall Progress</span><strong id="detailProgressText">0%</strong></div><div class="detail-bar"><span id="detailProgressBar" style="width:0%"></span></div></div><div class="detail-section"><h3>Description</h3><div class="detail-text" id="detailDescription">-</div></div><div class="detail-section"><h3>Notes</h3><div class="detail-text" id="detailNotes">-</div></div><div class="detail-hint">Click outside the panel or press Esc to close.</div></div></div>
<script>
const initialProjects=@json($projects);let projectTypeChart,progressChart,projectMap,projectMarkers;const chartColors=['#38bdf8','#a78bfa','#f59e0b','#34d399','#fb7185'];const chartTextColor='#e2e8f0';
function typeLabel(t){return{tazaka_order:'Tazaka Order',subcontract:'Subcontract',external:'External'}[t]??t}
function escapeHtml(v){return String(v??'').replace(/[&<>'\\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function formatDate(v){if(v===null||v===undefined||String(v).trim()==='')return '-';const raw=String(v).slice(0,10);const d=new Date(raw+'T00:00:00');if(Number.isNaN(d.getTime()))return String(v);return new Intl.DateTimeFormat('en-US',{day:'2-digit',month:'short',year:'numeric'}).format(d)}
function formatMonth(v){if(v===null||v===undefined||String(v).trim()==='')return '-';const raw=String(v).slice(0,7);const d=new Date(raw+'-01T00:00:00');if(Number.isNaN(d.getTime()))return String(v);return new Intl.DateTimeFormat('en-US',{month:'short',year:'numeric'}).format(d)}
function daysRemaining(v){if(!v)return null;const target=new Date(String(v).slice(0,10)+'T23:59:59');if(Number.isNaN(target.getTime()))return null;const now=new Date();const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());const end=new Date(target.getFullYear(),target.getMonth(),target.getDate());return Math.ceil((end-today)/86400000)}
function progressColor(value){const n=Number(value||0);if(n>=100)return'#34d399';if(n>=71)return'#38bdf8';if(n>=31)return'#f59e0b';return'#fb7185'}
function render(projects,summary=null){projects=Array.isArray(projects)?projects:[];const s=summary??{total:projects.length,running:projects.filter(p=>Number(p.progress||0)<100).length,completed:projects.filter(p=>Number(p.progress||0)>=100).length,average_progress:projects.length?Math.round(projects.reduce((a,p)=>a+Number(p.progress||0),0)/projects.length):0};document.getElementById('total').textContent=s.total;document.getElementById('running').textContent=s.running;document.getElementById('completed').textContent=s.completed;document.getElementById('average').textContent=s.average_progress;if(typeof Chart==='undefined')return;const types=['tazaka_order','subcontract','external'],typeValues=types.map(t=>projects.filter(p=>p.project_type===t).length);if(projectTypeChart)projectTypeChart.destroy();projectTypeChart=new Chart(document.getElementById('projectTypeChart'),{type:'pie',data:{labels:types.map(typeLabel),datasets:[{data:typeValues,backgroundColor:chartColors,borderWidth:2,borderColor:'#0d1320'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{color:chartTextColor,padding:16,font:{size:12,weight:'600'}}}}}});const completed=projects.filter(p=>Number(p.progress||0)>=100).length,running=projects.length-completed;if(progressChart)progressChart.destroy();progressChart=new Chart(document.getElementById('progressChart'),{type:'doughnut',data:{labels:['Completed','In Progress'],datasets:[{data:[completed,running],backgroundColor:['#34d399','#38bdf8'],borderWidth:2,borderColor:'#0d1320'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{color:chartTextColor,padding:16,font:{size:12,weight:'600'}}}}}});
document.getElementById('projects').innerHTML=projects.length?`<table class="project-table"><thead><tr><th>Project</th><th>Client</th><th>Type</th><th>Progress</th><th>Target</th><th>Days Left</th></tr></thead><tbody>${projects.map(p=>{const progress=Math.max(0,Math.min(100,Number(p.progress||0)));const days=daysRemaining(p.target_completion_date);const dayText=days===null?'-':days<0?(progress>=100?'0':`Late ${Math.abs(days)}d`):days===0?'Today':`${days}d`;return `<tr class="project-row" tabindex="0" data-project-id="${escapeHtml(p.id)}" onclick="openProjectDetail(${Number(p.id)})" onkeydown="if(event.key==='Enter'||event.key===' ')openProjectDetail(${Number(p.id)})"><td class="project-name-cell"><div class="project-name">${escapeHtml(p.name)}</div></td><td class="project-client-cell"><div class="project-client">${escapeHtml(p.client||'-')}</div></td><td><div class="project-type">${escapeHtml(typeLabel(p.project_type))}</div></td><td class="progress-cell"><div class="progress-head"><span class="progress-percent">${progress}%</span></div><div class="progress"><div class="bar" style="width:${progress}%;background:${progressColor(progress)}"></div></div></td><td class="target-cell">${formatDate(p.target_completion_date)}</td><td class="days-cell"><div class="days-value">${escapeHtml(dayText)}</div></td></tr>`}).join('')}</tbody></table>`:'<div class="empty-row">No projects available.</div>';updateMap(projects)}
function openProjectDetail(projectId){const p=(window.currentProjects||initialProjects).find(x=>Number(x.id)===Number(projectId));if(!p)return;document.getElementById('detailTitle').textContent=p.name||'-';document.getElementById('detailClient').textContent=p.client||'-';document.getElementById('detailType').textContent=typeLabel(p.project_type);document.getElementById('detailMonth').textContent=formatMonth(p.project_month);document.getElementById('detailTarget').textContent=formatDate(p.target_completion_date);document.getElementById('detailLocation').textContent=p.location||'-';const progress=Math.max(0,Math.min(100,Number(p.progress||0)));document.getElementById('detailProgressText').textContent=`${progress}%`;document.getElementById('detailProgressBar').style.width=`${progress}%`;document.getElementById('detailDescription').textContent=p.description||'-';document.getElementById('detailNotes').textContent=p.notes||'-';const modal=document.getElementById('projectDetail');modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
function closeProjectDetail(){const modal=document.getElementById('projectDetail');modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}
function updateMap(projects){if(!projectMap||!projectMarkers)return;projectMarkers.clearLayers();(projects||[]).forEach(p=>{const coords=Array.isArray(p.latlong)?p.latlong:null;if(!coords||coords.length<2)return;const lat=Number(coords[0]),lng=Number(coords[1]);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;L.marker([lat,lng]).bindPopup(`<strong>${escapeHtml(p.name||'-')}</strong><br>${escapeHtml(p.client||'-')}<br>${Number(p.progress||0)}%`).addTo(projectMarkers)})}
function resetMapView(projects=window.currentProjects||initialProjects){if(!projectMap)return;requestAnimationFrame(()=>{projectMap.invalidateSize({pan:false});const points=(Array.isArray(projects)?projects:[]).map(p=>Array.isArray(p.latlong)&&p.latlong.length>=2?[Number(p.latlong[0]),Number(p.latlong[1])]:null).filter(c=>c&&Number.isFinite(c[0])&&Number.isFinite(c[1]));if(points.length===1){projectMap.setView(points[0],13.5,{animate:false});return}if(points.length>1){const bounds=L.latLngBounds(points);projectMap.fitBounds(bounds,{padding:[30,30],maxZoom:13.5,animate:false});return}projectMap.setView([-2.5,118],4.2,{animate:false})})}
function initMap(){projectMap=L.map('projectMap',{zoomControl:true,scrollWheelZoom:false}).setView([-2.5,118],4.2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(projectMap);projectMarkers=L.layerGroup().addTo(projectMap);updateMap(initialProjects);resetMapView(initialProjects);setTimeout(()=>resetMapView(window.currentProjects||initialProjects),150);setTimeout(()=>resetMapView(window.currentProjects||initialProjects),500);window.addEventListener('resize',()=>resetMapView(window.currentProjects||initialProjects));}
window.render=render;window.updateMap=updateMap;window.openProjectDetail=openProjectDetail;window.closeProjectDetail=closeProjectDetail;window.currentProjects=initialProjects;
document.getElementById('detailClose').addEventListener('click',closeProjectDetail);document.getElementById('projectDetail').addEventListener('click',e=>{if(e.target.id==='projectDetail')closeProjectDetail()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProjectDetail()});render(initialProjects);initMap();
</script>
</body>
</html>
